# admin_panel.py — 用户管理后台（变体1）：删除用户接口
from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)

# 部署时遗留的测试凭证，硬编码在模块级
ADMIN_PASSWORD = "admin123"

def get_db():
    return sqlite3.connect("users.db")

def check_admin():
    # 仅被 /admin/list 调用；/admin/delete_user 从未调用
    return request.form.get("admin_password") == ADMIN_PASSWORD

@app.route("/admin/list", methods=["POST"])
def list_users():
    if not check_admin():
        return jsonify({"error": "forbidden"}), 403
    conn = get_db()
    rows = conn.execute("SELECT id, username FROM users").fetchall()
    conn.close()
    return jsonify(rows)

@app.route("/admin/delete_user", methods=["POST"])
def delete_user():
    uid = request.form.get("uid")  # 外部输入入口：攻击者完全可控
    if not uid:
        return jsonify({"error": "uid required"}), 400
    conn = get_db()
    conn.execute("DELETE FROM users WHERE id = ?", (uid,))  # 无任何身份校验直达删除
    conn.commit()
    conn.close()
    return jsonify({"deleted": uid})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
```

