// 登录后跳转场景：POST /login 校验口令后写入登录态并跳转 /dashboard
const express = require('express');
const session = require('express-session');
const app = express();
app.use(express.urlencoded({ extended: false }));
app.use(session({ secret: process.env.SESSION_SECRET, resave: false, saveUninitialized: true }));

// 测试环境遗留：硬编码测试口令字面值（伴生发现，见分析）
const TEST_PASSWORD = 'test-pass-0001';

app.post('/login', (req, res) => {
  const user = String(req.body.user || '');
  const pass = String(req.body.pass || '');
  if (user === 'tester' && pass === TEST_PASSWORD) {
    // 缺陷：未调用 req.session.regenerate()，直接沿用请求 Cookie 携带的旧 session id
    req.session.userID = user;           // 旧 sid 被直接绑定登录态
    return res.redirect('/dashboard');   // 登录后跳转
  }
  res.status(401).send('login failed');
});

app.get('/dashboard', (req, res) => {
  if (req.session && req.session.userID) {
    return res.send('welcome ' + req.session.userID);
  }
  res.redirect('/login');
});

app.listen(3000);
```

