```javascript
const express = require('express');
const cookieParser = require('cookie-parser');
const app = express();
app.use(express.urlencoded({ extended: false }));
app.use(cookieParser());

// 前后端共享的固定口令：写死在代码里，随前端包分发，任何访问者可提取
const PROFILE_API_SECRET = 'team-internal-2024-static-key';

// 会话仅靠 Cookie 标识；登录后服务端不再做任何请求级校验
const sessions = { 'sid-alice': { id: 'alice', profile: 'hello' } };

app.post('/profile/update', (req, res) => {
  // 唯一防线：假设请求来自同源页面，仅比对固定口令，无 CSRF token
  if (req.body.api_key !== PROFILE_API_SECRET) {
    return res.status(403).json({ error: 'bad key' });
  }
  const sess = sessions[req.cookies.sid];
  if (!sess) return res.status(401).json({ error: 'login first' });
  // 用户可控的 profile 字段直接覆盖资料，未校验请求真实来源
  sess.profile = String(req.body.profile || '');
  res.json({ ok: true, profile: sess.profile });
});

app.listen(3000);
